define(['core/ajax','core/notification'], function(Ajax, Notification){
 let cfg, users=new Map(), dragged=null;
 const chip=(u)=>{const d=document.createElement('div');d.className='wsg-student-chip';d.draggable=true;d.dataset.userid=u.id;d.innerHTML=`<span class="wsg-avatar">${(u.name||'?').slice(0,2)}</span><span><strong></strong><small></small></span><span class="wsg-drag">⋮⋮</span>`;d.querySelector('strong').textContent=u.name;d.querySelector('small').textContent=u.email||'';return d;};
 const bindChip=(el)=>{el.addEventListener('dragstart',()=>{dragged=el;el.classList.add('is-dragging');});el.addEventListener('dragend',()=>{el.classList.remove('is-dragging');dragged=null;refreshCounts();dirty();});};
 const bindZone=(z)=>{z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('is-over');});z.addEventListener('dragleave',()=>z.classList.remove('is-over'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('is-over');if(dragged)z.appendChild(dragged);});};
 const newTeam=(name='Nhóm mới')=>{const s=document.createElement('section');s.className='wsg-team-card';s.dataset.teamid='0';s.innerHTML=`<div class="wsg-team-card-head"><input class="form-control wsg-team-name" aria-label="Tên nhóm"><span class="badge bg-light text-dark" data-region="team-count">0 thành viên</span><button type="button" class="btn btn-sm btn-link text-danger" data-action="remove-team">×</button></div><div class="wsg-team-dropzone" data-dropzone="1"></div>`;s.querySelector('input').value=name;s.querySelector('[data-action="remove-team"]').addEventListener('click',()=>{const pool=document.querySelector('[data-region="unassigned"]');s.querySelectorAll('.wsg-student-chip').forEach(c=>pool.appendChild(c));s.remove();refreshCounts();dirty();});bindZone(s.querySelector('[data-dropzone]'));return s;};
 const layout=()=>Array.from(document.querySelectorAll('.wsg-team-card')).map((t,i)=>({id:Number(t.dataset.teamid||0),name:t.querySelector('.wsg-team-name')?.value||`Nhóm ${i+1}`,members:Array.from(t.querySelectorAll('.wsg-student-chip')).map(x=>Number(x.dataset.userid)),representativeuserid:Number(t.querySelector('.wsg-student-chip')?.dataset.userid||0)})).filter(t=>t.members.length||t.id);
 const dirty=()=>{const s=document.querySelector('[data-region="save-status"]');if(s){s.textContent='Có thay đổi chưa lưu';s.classList.add('text-warning');}};
 const refreshCounts=()=>{document.querySelectorAll('.wsg-team-card').forEach(t=>{const n=t.querySelectorAll('.wsg-student-chip').length;t.querySelector('[data-region="team-count"]').textContent=`${n} thành viên`;});const un=document.querySelector('[data-region="unassigned"]')?.querySelectorAll('.wsg-student-chip').length||0;const e=document.querySelector('[data-region="unassigned-count"]');if(e)e.textContent=`${un} học sinh`;};
 const rebuild=(canonical)=>{const area=document.querySelector('[data-region="teams"]'),pool=document.querySelector('[data-region="unassigned"]');area.innerHTML='';const assigned=new Set();canonical.forEach((t,i)=>{const s=newTeam(t.name||`Nhóm ${i+1}`);s.dataset.teamid=t.id||0;(t.members||[]).forEach(id=>{assigned.add(Number(id));const u=users.get(Number(id));if(u){const c=chip(u);bindChip(c);s.querySelector('[data-dropzone]').appendChild(c);}});area.appendChild(s);});pool.innerHTML='';users.forEach((u,id)=>{if(!assigned.has(id)){const c=chip(u);bindChip(c);pool.appendChild(c);}});refreshCounts();};
 const save=async()=>{const btn=document.querySelector('[data-action="save-layout"]');btn.disabled=true;try{const r=await Ajax.call([{methodname:'mod_worksheetgrader_save_team_layout',args:{sessionid:cfg.sessionid,layoutjson:JSON.stringify(layout())}}])[0];rebuild(JSON.parse(r.layoutjson));const s=document.querySelector('[data-region="save-status"]');s.textContent=`Đã lưu ${r.teamcount} nhóm · ${r.assignedcount} học sinh`;s.classList.remove('text-warning');s.classList.add('text-success');}catch(e){Notification.exception(e);}finally{btn.disabled=false;}};
 const balance=()=>{let count=Number(prompt('Số nhóm muốn tạo:',Math.max(1,document.querySelectorAll('.wsg-team-card').length||4)));if(!count||count<1)return;const all=Array.from(users.values());const canonical=Array.from({length:Math.min(count,all.length)},(_,i)=>({id:0,name:`Nhóm ${i+1}`,members:[]}));all.forEach((u,i)=>canonical[i%canonical.length].members.push(u.id));rebuild(canonical);dirty();};
 const init=(config)=>{cfg=config;(cfg.students||[]).forEach(u=>users.set(Number(u.id),u));document.querySelectorAll('.wsg-student-chip').forEach(bindChip);document.querySelectorAll('[data-dropzone]').forEach(bindZone);document.querySelectorAll('[data-action="remove-team"]').forEach(b=>b.addEventListener('click',()=>{const s=b.closest('.wsg-team-card'),pool=document.querySelector('[data-region="unassigned"]');s.querySelectorAll('.wsg-student-chip').forEach(c=>pool.appendChild(c));s.remove();refreshCounts();dirty();}));document.querySelector('[data-action="add-team"]')?.addEventListener('click',()=>{document.querySelector('[data-region="teams"]').appendChild(newTeam(`Nhóm ${document.querySelectorAll('.wsg-team-card').length+1}`));dirty();});document.querySelector('[data-action="auto-balance"]')?.addEventListener('click',balance);document.querySelector('[data-action="save-layout"]')?.addEventListener('click',save);document.querySelector('[data-action="student-search"]')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-region="unassigned"] .wsg-student-chip').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q));});document.querySelectorAll('.wsg-team-name').forEach(i=>i.addEventListener('input',dirty));refreshCounts();};return {init};
});
